#include "core/backends/anan_original/AnanDroopDefaults.h"

#include "core/backends/anan_original/P2Protocol.h"

#include <algorithm>
#include <array>

namespace AetherSDR::anan_original {
namespace {

//DH1KLM Pure data, generated by tools/derive_droop_from_gateware.py. Kept in its own
//DH1KLM file so regenerating it cannot clobber the lookup below.
#include "core/backends/anan_original/AnanDroopDefaultTables.inc"

//DH1KLM The .inc emits std::array<float, 1024>, which IS DroopCorrectionTable --
//DH1KLM assert rather than assume, so a regeneration at a different bin count is a
//DH1KLM compile error here instead of a silent no-op at apply time (see
//DH1KLM applyDroopCorrectionDb()'s own size handling).
static_assert(kDroopCorrectionGw27.size() == kDroopCorrectionFftSize,
              "generated default table must match the droop storage grid");

}  // namespace

const DroopCorrectionTable* defaultDroopTableForRate(int rateKsps) noexcept
{
    //DH1KLM One table serves every rate; the lookup exists to reject rates this
    //DH1KLM radio cannot run, not to choose between curves. See the header.
    //DH1KLM kDdc0RatesKsps, not a local copy: AnanRxDsp::setDroopCorrectionTable()
    //DH1KLM validates against that same list, so a seventh rate added there but not
    //DH1KLM here would be accepted by the DSP while this returned nullptr for it --
    //DH1KLM the rate would ship with no default and nothing would fail.
    return std::find(kDdc0RatesKsps.begin(), kDdc0RatesKsps.end(), rateKsps)
            != kDdc0RatesKsps.end()
        ? &kDroopCorrectionGw27
        : nullptr;
}

const std::array<int, 6>& defaultDroopRatesKsps() noexcept
{
    return kDdc0RatesKsps;
}

}  // namespace AetherSDR::anan_original
